package com.supportsphere.util; import java.nio.charset.StandardCharsets; import java.security.*; public final class PasswordUtil { private PasswordUtil(){} public static String sha256(String s){try{MessageDigest md=MessageDigest.getInstance("SHA-256"); byte[] b=md.digest(s.getBytes(StandardCharsets.UTF_8)); StringBuilder x=new StringBuilder(); for(byte v:b)x.append(String.format("%02x",v)); return x.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
